add('sdk','SASKI SDK — De-risk Human-Facing AI','De-risk human-facing AI applications with deterministic pre- and post-LLM governance. Apply privacy, safety, and policy controls with inspectable decision evidence.',hero('SASKI SDK / Interaction governance','Put policy around<br> the conversation.','Add an independent safety layer before and after the model for applications that interact with people.')+section('How SASKI fits','Govern the full application flow.',sdk_architecture,'soft')+section('The interaction boundary','Govern the input. Review the output.',cards([('Before the model','Protect sensitive input','Apply configured PII redaction and policy checks before content reaches the model.',''),('During the workflow','Route consequential signals','Use deterministic crisis and escalation handling within the configured application workflow.',''),('After the model','Validate the response','Evaluate the model’s output against configured boundaries before returning it to the user.','')]))+section('Built around your context','Different users. Different policy needs.','<div class="split"><p class="lead">De-risk the application with controls that reflect its users, data, and consequences.</p><div><p>SASKI SDK separates governance policy from the model’s conversational instructions. Choose the relevant configuration and validate it against representative traffic.</p><p>Start with an evaluation or Shadow Mode discussion to understand the decisions SASKI would make without changing production responses.</p>'+link('findings','Explore the evidence behind the approach ↗','text-link')+'</div></div>','soft')+section('Operational efficiency','Spend tokens on the conversation.','<p class="lead narrow">Moving suitable repeated instructions into deterministic controls can reduce prompt overhead. Estimate the effect using your own traffic and input-token price.</p>'+link('tokenator','Try the Tokenator ↗','text-link')),'Product')
add('replay','SASKI Replay — Policy Evaluation & Evidence','Evaluate historical AI interactions and agent actions against SASKI policy to examine risk, compare decisions, and generate governance evidence.',hero('SASKI Replay / Evaluation & evidence','Look back.<br> Govern the next step.','Run historical interactions and proposed agent actions against policy to see how SASKI would evaluate them.')+section('Before enforcement','Test policy against the work you actually do.',cards([('Select','Define the evaluation','Choose representative historical traffic and the policy configuration to assess.',''),('Replay','Examine the decisions','Review what the configured controls would permit, intercept, or route for approval.',''),('Review','Build the evidence','Inspect decision records and use the findings to inform your integration and policy choices.','')]))+section('A practical starting point','Learn without changing production behavior.','<div class="split"><p class="lead">Replay creates a controlled space to examine policy behavior before a live rollout.</p><div><p>Use historical interactions to investigate governance gaps, compare policy configurations, or prepare a focused demonstration for your team.</p><p>Replay results describe the supplied records and tested policy. They do not establish complete coverage of future traffic or prove that a production action actually occurred.</p>'+link('contact-us','Discuss a Replay evaluation ↗','text-link')+'</div></div>','soft'),'Product')
add('how-it-works','How SASKI Works — Independent Governance','Learn how SASKI separates AI reasoning from policy enforcement across agent actions, human-facing interactions, and historical evaluations.',hero('Architecture','Intelligence and authority.<br> Separate by design.','An AI model proposes a response or action. Independent governance determines how it may proceed.')+section('The governing principle','AI understands. SASKI governs.',flow)+section('One approach, across your environment','Place the control where it matters.',cards(products),'soft')+section('Implementation matters','Make the governed path the real path.','<div class="split"><div><h3>Define the scope</h3><p>Identify protected actions, data flows, policies, and approval owners. Route relevant requests through the control layer and account for alternative execution paths.</p></div><div><h3>Verify the integration</h3><p>Test normal, denied, approval-required, and failure scenarios. Review decision receipts alongside system records to distinguish a policy decision from completed execution.</p></div></div>')+section('Evidence & attestation','Retain an inspectable decision trail.','<p class="lead narrow">Cryptographic receipts support verification of governance records. The meaning of that evidence depends on the configured policy, integrated execution path, and surrounding system logs.</p>','soft'))
failure=[('01','Data leaves before redaction','Sensitive input reaches the network before the application applies a privacy control.'),('02','Crisis signals follow the normal route','A consequential safety signal is processed as an ordinary conversational turn.'),('03','A handoff is described but never executed','The response claims an escalation, while the corresponding action record is absent.'),('04','Data requests receive only reassurance','A conversational acknowledgment is not matched by a verified data-handling event.'),('05','Internal information is exposed','An insufficiently protected endpoint returns prompts, configuration, or internal reasoning.'),('06','The conversation exceeds its intended role','A support or administrative assistant moves into professional guidance beyond its intended scope.')]
