add('findings','Findings — Pre-LLM Infrastructure Failures','Six recurring failure classes from SASKI’s evaluations of production AI chatbots, covering data handling, escalation, access, and application boundaries.',hero('Research / Findings','The response is only<br> part of the story.','SASKI’s evaluations examine what happens around the model: the network payload, the control path, and the record of what actually ran.')+'<article class="wrap article"><p class="eyebrow">Pre-LLM infrastructure failures</p><p class="lead">Six recurring failure classes appeared in SASKI’s published evaluations of human-facing AI deployments.</p>'+findbody+'<section class="method"><h2>Method & scope</h2><p>The evaluation series used the Cooperative Extraction Method alongside browser network inspection. The source inventory records responsible disclosure before publication. These observations describe the evaluated deployments and configurations; they are not a claim about every AI application.</p><p>The 2026 series includes healthcare, student-support, enterprise chatbot, and medical-AI evaluations. This page preserves the core findings in a condensed form without carrying forward unreviewed legal conclusions.</p>'+link('sdk','Explore the SASKI SDK approach ↗','text-link')+'</section></article>','Article')
add('resources','Resources — AI Governance & Token Savings','Explore SASKI’s governance findings, architecture, and Tokenator calculator for estimating repeated input-token overhead.',hero('Resources','Make the case.<br> Examine the evidence.','Practical starting points for understanding independent governance and evaluating it in your environment.')+section('Explore','Research, architecture, and economics.',cards([('Research','Findings','Examine six infrastructure failure classes from evaluations of production AI chatbots.','findings'),('Calculator','Token Savings / Tokenator','Model repeated prompt-token overhead using your own assumptions.','tokenator'),('Architecture','How SASKI Works','Understand the separation between AI reasoning and independent policy enforcement.','how-it-works')])) )
calc='''<div class="calculator"><form id="calculator" class="calc-fields"><h2>Your assumptions</h2><p>Illustrative defaults. Replace them with your own measured values.</p><label for="turns">Monthly model calls</label><input id="turns" type="number" min="0" max="1000000000000" step="1" value="1000000" required><label for="legacy">Current repeated prompt tokens per call</label><input id="legacy" type="number" min="0" max="10000000" step="1" value="450" required><label for="lean">Proposed repeated prompt tokens per call</label><input id="lean" type="number" min="0" max="10000000" step="1" value="150" required><label for="price">Input price per million tokens (USD)</label><input id="price" type="number" min="0" max="100000" step="0.01" value="2.50" required><button class="button" type="submit">Calculate estimate <span aria-hidden="true">↗</span></button></form><div class="calc-result" aria-live="polite" aria-atomic="true"><p class="eyebrow">Estimated prompt overhead reduction</p><p class="result-number" id="monthly">$750.00</p><p>per month</p><div class="result-details"><p><strong id="annual">$9,000.00</strong><span>Annualized estimate</span></p><p><strong id="tokens">300,000,000</strong><span>Fewer input tokens per month</span></p><p><strong id="percent">66.7%</strong><span>Reduction in repeated prompt tokens</span></p></div><p id="calc-note">This estimate covers repeated input tokens only.</p></div></div>'''
add('tokenator','Tokenator — Estimate Prompt Token Savings','Estimate monthly and annual repeated input-token savings using your call volume, prompt sizes, and input-token price. A transparent planning calculator.',hero('Resources / Token Savings','Less repetition.<br> More useful context.','Estimate the input-token cost of repeating governance instructions on every call. All calculations run in your browser.')+'<section class="section"><div class="wrap">'+calc+'<noscript><p>Enable JavaScript to calculate an estimate. The displayed values use the illustrative defaults.</p></noscript></div></section>'+section('Transparent assumptions','Know what the number means.','<div class="split"><div><h3>The calculation</h3><p>Monthly reduction = monthly calls × (current tokens − proposed tokens) × input price ÷ 1,000,000. Annualized reduction is the monthly result multiplied by 12.</p></div><div><h3>The scope</h3><p>This planning estimate excludes output tokens, caching discounts, blocked calls, variable safety context, integration costs, and SASKI fees. It is not a quote or a performance guarantee. Validate any removal of prompt instructions against your application’s policy needs.</p></div></div>','soft'))
add('about','About SASKI Institute PBC','SASKI Institute PBC develops independent, deterministic governance for AI agents and human-facing applications, with inspectable decision evidence.',hero('About SASKI Institute','Accountability belongs<br> in the architecture.','We develop independent governance infrastructure for AI systems that interact with people and act in the world.')+section('Our purpose','Make consequential AI decisions inspectable.','<div class="split"><p class="lead">SASKI Institute is a public benefit corporation focused on more accountable AI.</p><div><p>We believe the ability to generate an answer should be separated from the authority to take an action. Explicit policy, independent enforcement, and verifiable records are the foundations of that approach.</p><p>Our product family connects action governance through SASKI Agentic, smart-home governance through SASKI Estate, interaction governance through SASKI SDK, and evaluation through SASKI Replay.</p></div></div>')+section('Our work','From infrastructure findings to independent controls.',cards(products),'soft'))
